// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 warpTime, uint256 rollBlock, address sender) public {
        vm.assume(warpTime >= 1);
        vm.assume(rollBlock >= 1 && rollBlock <= type(uint64).max);
        vm.assume(sender != address(0));

        vm.deal(sender, 20 ether);
        vm.warp(warpTime);
        vm.roll(rollBlock);

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("\x00");

        if (ok) {
            uint256 stored = c.pastBlockTime();
            assertTrue(stored == block.timestamp);
        } else {
            uint256 stored = c.pastBlockTime();
            assertTrue(stored == stored);
        }
    }
}
